ALTER TABLE Customers ADD tier varchar(20) NOT NULL DEFAULT 'STANDARD';
CREATE TABLE Campaigns(id varchar(36) PRIMARY KEY,name nvarchar(120) NOT NULL,channel nvarchar(80) NOT NULL,startsAt datetime2 NOT NULL,endsAt datetime2 NOT NULL,budget int NOT NULL DEFAULT 0 CHECK(budget>=0),draft nvarchar(2000) NOT NULL DEFAULT '',CHECK(endsAt>startsAt));
ALTER TABLE Bookings ADD source nvarchar(80) NOT NULL DEFAULT N'Trực tiếp',campaignId varchar(36) NULL REFERENCES Campaigns(id);
ALTER TABLE Stays ADD source nvarchar(80) NOT NULL DEFAULT N'Trực tiếp',campaignId varchar(36) NULL REFERENCES Campaigns(id);
CREATE TABLE Vouchers(id varchar(36) PRIMARY KEY,code varchar(40) NOT NULL UNIQUE,discount int NOT NULL CHECK(discount>0),minTotal int NOT NULL CHECK(minTotal>=0),startsAt datetime2 NOT NULL,endsAt datetime2 NOT NULL,maxUses int NOT NULL CHECK(maxUses>0),perCustomer int NOT NULL CHECK(perCustomer>0),enabled bit NOT NULL DEFAULT 1,CHECK(endsAt>startsAt));
CREATE TABLE VoucherRedemptions(id varchar(36) PRIMARY KEY,voucherId varchar(36) NOT NULL REFERENCES Vouchers(id),customerId varchar(36) NOT NULL REFERENCES Customers(id),invoiceId varchar(36) NOT NULL UNIQUE REFERENCES Invoices(id),amount int NOT NULL CHECK(amount>0),createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE AiUsage(actorKey varchar(80) NOT NULL,usageDate date NOT NULL,calls int NOT NULL,PRIMARY KEY(actorKey,usageDate));
CREATE TABLE Incidents(id varchar(36) PRIMARY KEY,roomId varchar(36) NOT NULL REFERENCES Rooms(id),reportedBy varchar(36) NOT NULL REFERENCES Users(id),description nvarchar(500) NOT NULL,status varchar(12) NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESOLVED')),resolution nvarchar(500) NULL,createdAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),resolvedAt datetime2 NULL);
